<template>
	<view :class="zyThemeClass" class="growth-page music-page"><view class="growth-header"><text class="growth-eyebrow">ZHIYU / SOUND ROOM</text><AccessibleButton class="credits-button zy-link" @click="goCredits"><text>素材来源</text><ZyIcon name="external" :size="24" tone="brand" /></AccessibleButton></view><text class="growth-title">给耳朵，一段慢时光。</text><text class="growth-subtitle">选一段喜欢的旋律。不必追求任何状态。</text>
<view class="listening-card"><view class="record" :class="{playing,reduced:reducedMotion}"><view class="record-center"><XiaotuanPet :size="56" face="sleepy" aria-hidden="true"/></view></view><text class="now-label" role="status" aria-live="polite">{{playing?'正在聆听':loading?'正在准备':'准备好时，再开始'}}</text><text class="track-title">{{active.title}}</text><text class="track-credit">{{active.original}} · {{active.author}}</text><view class="seek-row"><text>{{time(position)}}</text><slider aria-label="播放进度" :value="position" :max="Math.max(duration,1)" :disabled="!duration" activeColor="#0E5B53" block-size="14" @change="seek"/><text>{{time(duration)}}</text></view><view class="player-controls"><AccessibleButton aria-label="上一首" size="icon" @click="change(-1)"><ZyIcon name="back" :size="32" tone="brand" /></AccessibleButton><AccessibleButton class="play-button" :disabled="loading" @click="toggle">{{loading?'加载中…':playing?'暂停':'开始聆听'}}</AccessibleButton><AccessibleButton aria-label="下一首" size="icon" @click="change(1)"><ZyIcon name="arrow" :size="32" tone="brand" /></AccessibleButton></view><view v-if="error" class="growth-error" role="alert"><text>{{error}}</text><AccessibleButton @click="retry">重新加载</AccessibleButton></view></view>
<view class="growth-card"><view class="setting-row"><text>定时停止</text><text class="growth-muted">{{remaining?time(remaining)+' 后停止':'本次未设置'}}</text></view><view class="timer-options"><AccessibleButton v-for="n in [0,5,15,30]" :key="n" :aria-pressed="timerMinutes===n" :class="{selected:timerMinutes===n}" @click="setTimer(n)">{{n?n+' 分钟':'关闭'}}</AccessibleButton></view><view class="setting-row"><text>音量</text><text class="growth-muted">{{volume}}%</text></view><slider aria-label="播放音量" :value="volume" activeColor="#0E5B53" block-size="14" @change="setVolume"/><text class="growth-muted">保持舒适音量；离开页面会自动暂停。</text></view>
<view class="section-heading"><text class="growth-card-title">选一段声音</text><text class="growth-muted">开放授权 · 本地播放源</text></view><AccessibleButton v-for="(track,i) in tracks" :key="track.id" class="track-row" :aria-pressed="i===index" :class="{selected:i===index}" @click="select(i)"><view class="track-symbol">{{i===index&&playing?'♫':'♪'}}</view><view class="track-info"><text>{{track.title}}</text><text class="growth-muted">{{track.tag}} · {{track.original}}</text></view><text>{{i===index?'已选择':'播放 →'}}</text></AccessibleButton><BreathingPractice/><XiaozhiCard @open="goChat"/><text class="growth-foot">音乐用于日常放松，不承诺治疗效果。<br/>本系统不能替代专业心理咨询</text></view></template>
<script setup>
import AccessibleButton from '../../components/AccessibleButton.vue'
import ZyIcon from '../../components/ZyIcon.vue'
import BreathingPractice from '../../components/BreathingPractice.vue'
import{ref,computed,onUnmounted}from'vue';import{createMusicAudio}from'../../utils/music-audio';import{onHide}from'@dcloudio/uni-app';import{tracks}from'../../data/music';import{API_BASE_URL}from'../../utils/config';import{useInteraction}from'../../composables/useInteraction';import XiaozhiCard from'../../components/XiaozhiCard.vue';import XiaotuanPet from'../../components/XiaotuanPet.vue';
const{reducedMotion}=useInteraction();const index=ref(0),active=computed(()=>tracks[index.value]),playing=ref(false),loading=ref(false),error=ref(''),position=ref(0),duration=ref(0),volume=ref(35),timerMinutes=ref(0),remaining=ref(0);let audio=null,tick=null,deadline=0,loadTimeout=null;
function clearLoad(){clearTimeout(loadTimeout);loadTimeout=null;loading.value=false}function destroy(){clearLoad();if(audio){audio.stop();audio.destroy();audio=null}playing.value=false}
function prepare(){destroy();error.value='';const a=createMusicAudio();audio=a;a.volume=volume.value/100;a.autoplay=false;a.src=API_BASE_URL+active.value.url;a.onPlay(()=>{if(audio!==a)return;playing.value=true;clearLoad()});a.onPause(()=>{if(audio===a)playing.value=false});a.onEnded(()=>{if(audio===a){playing.value=false;position.value=0}});a.onTimeUpdate(()=>{if(audio===a){position.value=a.currentTime||0;duration.value=a.duration||0}});a.onError(()=>{if(audio===a){clearLoad();playing.value=false;error.value='这段音乐暂时无法播放，请重试。'}});return a}
function play(){const a=audio||prepare();loading.value=true;loadTimeout=setTimeout(()=>{if(audio===a){a.pause();clearLoad();error.value='音乐加载较慢，请检查网络后重试。'}},15000);a.play()}
function toggle(){if(playing.value)audio.pause();else play()}function retry(){prepare();play()}function select(i){index.value=i;position.value=0;duration.value=0;prepare();play()}function change(delta){select((index.value+delta+tracks.length)%tracks.length)}function seek(e){audio?.seek(e.detail.value)}function setVolume(e){volume.value=e.detail.value;if(audio)audio.volume=volume.value/100}
function setTimer(n){clearInterval(tick);timerMinutes.value=n;remaining.value=n*60;deadline=Date.now()+n*60000;if(n)tick=setInterval(()=>{remaining.value=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(!remaining.value){audio?.pause();clearInterval(tick);timerMinutes.value=0}},250)}
function time(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0')}function pause(){audio?.pause();clearLoad();setTimer(0)}onHide(pause);onUnmounted(()=>{clearInterval(tick);destroy()});function goCredits(){uni.navigateTo({url:'/pages/music/credits'})}function goChat(){uni.navigateTo({url:'/pages/emotion/chat'})}
</script>

<style scoped>.music-page{max-width:850px}.credits-button{background:transparent;color:var(--zy-brand-700);font-size:var(--zy-text-micro, 22rpx);margin:0;padding:0}.listening-card{background:var(--zy-bg-tint-mint);border:1rpx solid var(--zy-border);border-radius:0;padding:36rpx 30rpx;text-align:center;margin:30rpx 0}.record{height:260rpx;width:260rpx;margin:0 auto 25rpx;border-radius:50%;background:repeating-radial-gradient(circle,#244a3e 0,#244a3e 5rpx,#2e5548 6rpx,#2e5548 8rpx);display:grid;place-items:center;box-shadow:0 15rpx 35rpx #1f493328}.record-center{border-radius:50%;background:var(--zy-card-bg,#fff);width:120rpx;height:120rpx;display:grid;place-items:center;overflow:hidden}.record.playing{animation:spin 25s linear infinite}.record.reduced{animation:none}.now-label{display:block;font-size:var(--zy-text-micro, 22rpx);color:var(--zy-brand-700);letter-spacing:3rpx}.track-title{display:block;font-size:var(--zy-text-title-lg, 40rpx);font-weight:600;margin:12rpx 0}.track-credit{font-size:var(--zy-text-micro, 22rpx);color:var(--zy-content)}.seek-row{display:flex;align-items:center;font-size:var(--zy-text-micro, 22rpx);color:var(--zy-content);margin:22rpx 0;font-variant-numeric:tabular-nums}.seek-row slider{flex:1}.player-controls{display:flex;justify-content:center;gap:22rpx;align-items:center}.player-controls button{margin:0;width:75rpx;background:var(--zy-card-bg);border-radius:0;color:var(--zy-brand-700);font-size:var(--zy-text-title-lg, 40rpx)}.player-controls .play-button{width:240rpx;border-radius:0;background:var(--zy-brand-700);color:white;font-size:var(--zy-text-body, 28rpx);padding:8rpx 0}.setting-row,.section-heading{display:flex;justify-content:space-between;align-items:center}.timer-options{display:flex;gap:12rpx;margin:24rpx 0 30rpx}.timer-options button{flex:1;font-size:var(--zy-text-caption, 24rpx);margin:0;background:var(--zy-bg);color:var(--zy-content);border-radius:0}.timer-options .selected{background:var(--zy-brand-700);color:white}.section-heading{margin:34rpx 0 18rpx}.track-row{display:flex;gap:24rpx;align-items:center;text-align:left;background:var(--zy-card-bg);border:1rpx solid var(--zy-border);border-radius:0;margin:14rpx 0;padding:22rpx;width:100%;font-size:var(--zy-text-caption, 24rpx);color:var(--zy-brand-700)}.track-row.selected{border-color:var(--zy-brand-700)}.track-info{flex:1;color:var(--zy-title)}.track-info text{display:block}.track-symbol{background:var(--zy-brand-50,#EEF5F1);font-size:var(--zy-text-title-lg, 40rpx);padding:10rpx 24rpx;border-radius:0}button::after{border:0}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.record.playing{animation:none}}</style>

<style scoped>.growth-header{display:flex;justify-content:space-between;align-items:center;gap:20rpx}.growth-header .growth-eyebrow{margin:0}.credits-button{flex-shrink:0}

/* ── v9 冷瓷展签收口 ── */
.music-page { padding: 36rpx 32rpx 120rpx; }
.music-page .growth-title { font-size: 56rpx; }
.listening-card { background: transparent; border: 0; border-top: 1rpx solid var(--zy-border); border-bottom: 1rpx solid var(--zy-border); border-radius: 0; padding: 32rpx 0; margin: 32rpx 0; }
.record { box-shadow: none; height: 240rpx; width: 240rpx; }
.record-center { border-radius: 50%; background: #f1f4f1; }
.now-label { color: var(--zy-brand-700); }
.track-title { font-family: var(--zy-font-display, serif); font-size: 48rpx; font-weight: 500; }
.track-credit { color: var(--zy-muted); }
.player-controls button { width: 76rpx; background: transparent; border: 1rpx solid var(--zy-border); border-radius: 0; color: var(--zy-brand-700); }
.player-controls .play-button { width: 260rpx; border-radius: 0; background: var(--zy-brand-600); border-color: var(--zy-brand-600); color: #fff; }
.timer-options button { background: transparent; border: 1rpx solid var(--zy-border); border-radius: 0; }
.timer-options .selected { background: var(--zy-brand-600); border-color: var(--zy-brand-600); }
.track-row { background: transparent; border: 0; border-top: 1rpx solid var(--zy-border); border-radius: 0; padding: 20rpx 0; }
.track-row.selected { border-color: var(--zy-border); }
.track-symbol { background: var(--zy-bg-sunken); border-radius: 0; color: var(--zy-brand-700); }
.section-heading { border-bottom: 1rpx solid var(--zy-border); padding-bottom: 12rpx; }
.section-heading .growth-card-title { font-family: var(--zy-font-display, serif); font-size: 38rpx; font-weight: 500; }
.timer-options button{border:0;border-bottom:2rpx solid transparent;border-radius:0;background:transparent;color:var(--zy-muted,#6e7b75);padding:8rpx 10rpx}.timer-options .selected{background:transparent;color:var(--zy-brand-700,#0a403b);border-bottom-color:var(--zy-brand-700,#0a403b)}
</style>
